property.code:
require.config({
  paths: {
    pageRelation: new XWiki.Document(XWiki.Model.resolve('OpenProject.Code.PageRelationLoadJSX',
      XWiki.EntityType.DOCUMENT, XWiki.currentDocument.documentReference)).getURL('jsx', 'r=1')
  }
});
define('openproject.ckeditor.workPackageSearch', {
  prefix: 'openproject.ckeditor.workPackageSearch.',
  keys: ['noConnection', 'connectionError', 'searchFailed']
});
require(['deferred!ckeditor', 'jquery', 'pageRelation', 'xwiki-l10n!openproject.ckeditor.workPackageSearch'],
    function (ckeditorPromise, $, pageRelation, l10n) {
  // The instance parameter of the inserted macros is left out when the work packages come from the default connection,
  // so that the macros follow the default connection, as when they are inserted from the macro dialog.
  const search = function (text, callback, instance, isDefaultConnection) {
    let cfg = { query: { filters: [{ property: "summary", constraints: [{ operator: "contains", value: text }] }] } };
    const searchURL = XWiki.contextPath + '/rest/wikis/' + XWiki.currentWiki + '/projectmanagement/openproject/workitems';
    Promise.resolve($.getJSON(searchURL, { instance: instance, filter: JSON.stringify(cfg)}))
      .then(function (results) {
        if (!Array.isArray(results?.items)) {
          return [];
        }
        return results.items.map(wp => {
          return {
            id: wp.identifier.value,
            value: wp.identifier.value,
            label: wp.summary.value,
            typebadge: wp.type,
            projectbadge: wp.project.value,
            // The selected text is replaced with nothing and then the macro is inserted, after the autocomplete
            // panel is closed. Using a command instead of the outputTemplate also works on XWiki versions where
            // AdvancedAutoComplete ignores the outputTemplate (e.g. 15.10). When the parent pom moves to XWiki
            // 17.10.x, whose AdvancedAutoComplete uses the outputTemplate, the outputTemplate can be used instead.
            command: {
              name: 'xwiki-macro-insert',
              data: {
                name: 'openproject',
                inline: 'enforce',
                parameters: {
                  ...(isDefaultConnection ? {} : {instance}),
                  source: 'list',
                  displayer: 'inline'
                },
                // The macro content is written only when it's a string. The work package is listed by its key when
                // it has one, as OpenProject displays it (and as the picker of the macro editor writes it).
                content: String(wp.key || wp.identifier.value)
              }
            }
          };
        });
      }, function (xhr) {
        console.log(`Failed to search the work packages at [${searchURL}]: ${xhr?.status} ${xhr?.statusText}`);
        return getFailureItems(instance);
      })
      .catch(function (error) {
        console.log(`Failed to read the work packages found at [${searchURL}]: ${error}`);
        return getFailureItems(instance);
      })
      // Called once, outside of the promise chain, so that its own failures aren't taken for search failures.
      .then(items => setTimeout(() => callback(items), 0));
  };
  const DEFAULT_MARKER = '#';
  // The minimum number of characters to type after the marker for the work packages to be searched.
  const MIN_CHARS = 3;
  // A text that can be the beginning of a work package key (e.g. XWIKI-123), see OpenProjectWorkItemFields: a bare
  // identifier, and an identifier followed by a dash and digits.
  const IDENTIFIER = /^[A-Za-z][A-Za-z0-9_]*$/;
  const KEY_BEGINNING = /^[A-Za-z][A-Za-z0-9_]*(-\d*)?$/;
  // The text to search, typed after the marker, with the non-breaking spaces replaced.
  const getSearchText = function (query, marker) {
    return query.substring(marker.length).replaceAll('\u00A0', ' ');
  };
  // Same rule as the one enforced by the administration form: 1 to 5 non space characters, different from the markers
  // already used by the editor.
  const VALID_MARKER = /^(?!(@|\/|\[\[|\{\{|img::)$)\S{1,5}$/;
  let markerPromise;
  // The marker is configured by the wiki administrators. It is fetched at runtime (once per page load) instead of
  // being rendered in this skin extension, because the skin extension is cached by the browser.
  const getMarker = function () {
    if (!markerPromise) {
      const configReference = XWiki.Model.resolve('OpenProject.Code.OpenProjectConfiguration',
        XWiki.EntityType.DOCUMENT, XWiki.currentDocument.documentReference);
      const url = new XWiki.Document(configReference).getRestURL(
        'objects/OpenProject.Code.OpenProjectConfigurationClass/0/properties/workPackageSearchMarker');
      markerPromise = Promise.resolve($.getJSON(url, { media: 'json' }))
        .then(property => {
          const marker = typeof property?.value === 'string' ? property.value.trim() : '';
          if (VALID_MARKER.test(marker)) {
            return marker;
          }
          if (marker) {
            console.warn(`Invalid OpenProject work package search marker [${marker}], using [${DEFAULT_MARKER}].`);
          }
          return DEFAULT_MARKER;
        })
        .catch(() => DEFAULT_MARKER);
    }
    return markerPromise;
  };
  let defaultConnectionPromise;
  // The default connection is resolved by the server (e.g. it is the only connection when there is a single one). It is
  // fetched at runtime (once per page load), from the content of this page, because the skin extension is cached by the
  // browser.
  const getDefaultConnection = function () {
    if (!defaultConnectionPromise) {
      const pluginReference = XWiki.Model.resolve('OpenProject.Code.CKEditorPlugin', XWiki.EntityType.DOCUMENT,
        XWiki.currentDocument.documentReference);
      // The default connection is only given to the users who can edit the current document.
      const url = new XWiki.Document(pluginReference).getURL('get', $.param({
        outputSyntax: 'plain',
        document: XWiki.Model.serialize(XWiki.currentDocument.documentReference)
      }));
      defaultConnectionPromise = Promise.resolve($.getJSON(url))
        .then(config => typeof config?.defaultConnection === 'string' ? config.defaultConnection : '')
        .catch(error => {
          // The failure isn't cached, so that the next search tries again.
          defaultConnectionPromise = null;
          throw error;
        });
    }
    return defaultConnectionPromise;
  };
  // The work packages are searched in the OpenProject connection of the page relation (e.g. the pages of an OpenProject
  // space), or else in the default connection. The promise is rejected when the connection can't be determined.
  const getConnection = function () {
    return Promise.resolve(pageRelation.get())
      .catch(xhr => {
        // The page has no relation. The other failures are reported, without falling back to the default connection.
        if (xhr?.status === 404) {
          return null;
        }
        throw xhr;
      })
      .then(relation => {
        const instance = relation?.clientParams?.instance;
        if (typeof instance === 'string' && instance.trim()) {
          return {instance};
        }
        return getDefaultConnection()
          .then(defaultConnection => defaultConnection ? {instance: defaultConnection, isDefault: true} : null);
      });
  };
  // The entry displayed instead of the work packages when there's no connection to search them in, or when it can't be
  // determined. Selecting it inserts nothing.
  const getHintItem = function (key) {
    return {
      id: 'openproject-work-package-search-' + key,
      label: l10n.get(key),
      hint: true
    };
  };
  // An entry displaying the given HTML message, rendered by the server. Its links are opened in a new tab, so that the
  // edited content isn't lost, and the links to connect an OpenProject account come back to the edited page.
  const getMessageItem = function (key, messageHTML) {
    const message = $('<div></div>').html(messageHTML);
    const content = message.children('.warningmessage').length ? message.children('.warningmessage') : message;
    content.find('a[href]').each(function () {
      const url = new URL(this.href, window.location.href);
      if (url.searchParams.has('redirectUrl')) {
        url.searchParams.set('redirectUrl', XWiki.currentDocument.getURL('view'));
        this.href = url.toString();
      }
      this.target = '_blank';
      this.rel = 'noopener';
    });
    return {
      id: 'openproject-work-package-search-' + key,
      label: content.text(),
      html: content.html(),
      hint: true
    };
  };
  // The messages telling the current user why they can't search the work packages of a connection, as displayed by the
  // macros (e.g. with a link to connect their OpenProject account), or an empty string if there's none, by connection
  // name. They're rendered by the content of this page, since this skin extension is cached by the browser, and kept
  // for the lifetime of the page, as the other configurations fetched at runtime.
  const notAuthorizedMessages = {};
  const getNotAuthorizedMessage = function (connection) {
    if (!notAuthorizedMessages[connection]) {
      const pluginReference = XWiki.Model.resolve('OpenProject.Code.CKEditorPlugin', XWiki.EntityType.DOCUMENT,
        XWiki.currentDocument.documentReference);
      const url = new XWiki.Document(pluginReference).getURL('get', $.param({outputSyntax: 'plain', connection}));
      notAuthorizedMessages[connection] = Promise.resolve($.getJSON(url))
        .then(response => typeof response?.notAuthorizedMessage === 'string' ? response.notAuthorizedMessage : '')
        .catch(error => {
          // The failure isn't cached, so that the next search tries again.
          delete notAuthorizedMessages[connection];
          throw error;
        });
    }
    return notAuthorizedMessages[connection];
  };
  // The entry displayed instead of the work packages when their search failed: the message of the macros when the
  // current user can't read the data of the connection (e.g. they aren't connected to OpenProject, or the connection
  // doesn't exist anymore), or else a generic message (e.g. the OpenProject server can't be reached).
  const getFailureItems = function (connection) {
    return getNotAuthorizedMessage(connection)
      .then(message => message ? getMessageItem('notAuthorized', message) : getHintItem('searchFailed'))
      .catch(() => getHintItem('searchFailed'))
      .then(item => [{...item, failure: true}]);
  };
  ckeditorPromise.then(ckeditor => {
    const hintItemTemplate = new ckeditor.template(
      `<li data-id="{id}" class="ckeditor-autocomplete-item openproject-work-package-search-hint"
          aria-disabled="true">
        <div class="ckeditor-autocomplete-item-head">
          <span class="ckeditor-autocomplete-item-label text-muted" style="white-space: normal;">{label}</span>
        </div>
      </li>`);

    function getOpenProjectPluginCfg(marker) {
      return {
        dataCallback: function (options, callback) {
          const text = getSearchText(options.query, marker);
          getConnection().then(connection => {
            if (connection) {
              search(text, callback, connection.instance, connection.isDefault);
            } else {
              callback([getHintItem('noConnection')]);
            }
          }, () => callback([getHintItem('connectionError')]));
        },
        marker: marker,
        // Ignored by the AdvancedAutoComplete of the supported XWiki versions, see requireMinChars.
        minChars: MIN_CHARS,
        itemsLimit: 10,
        itemTemplate:
          `<li data-id="{id}" class="ckeditor-autocomplete-item">
            <div class="ckeditor-autocomplete-item-head">
              <span class="ckeditor-autocomplete-item-label">{label}</span>
            </div>
            <div class="ckeditor-autocomplete-item-badges">
              <span class="badge ckeditor-autocomplete-item-badge">{typebadge}</span>
              <span class="badge ckeditor-autocomplete-item-badge">{projectbadge}</span>
            </div>
          </li>`
      };
    }

    // Enable the plugin for the CKEditor instances that have been already created.
    Object.values(ckeditor.instances).forEach(maybeEnableOpenProjectPlugin);
    Object.values(ckeditor.instances).forEach(openMacroDialogOnQuickInsert);
    // Enable the plugin for the CKEditor instances that are going to be created from now on.
    ckeditor.on('instanceCreated', (event) => {
      maybeEnableOpenProjectPlugin(event.editor);
      openMacroDialogOnQuickInsert(event.editor);
    });

    // The quick actions ("/") insert the macros that have no mandatory parameter without asking for their parameters.
    // The OpenProject macros are inserted through their dialog instead, so that the user chooses what they display
    // (e.g. the project whose details to display), as for the other ways of inserting a macro.
    function openMacroDialogOnQuickInsert(editor) {
      editor.on('beforeCommandExec', (event) => {
        const macroId = event.data.name === 'xwiki-macro-maybe-install-insert' && event.data.commandData?.id;
        if (typeof macroId === 'string' && macroId.startsWith('openproject')) {
          event.cancel();
          editor.execCommand('xwiki-macro', {name: macroId});
        }
      });
    }

    function maybeEnableOpenProjectPlugin(editor) {
      return Promise.all([waitForEditorReady(editor), getMarker()]).then(([editor, marker]) => {
        const autoComplete = new ckeditor.plugins.AdvancedAutoComplete(editor, getOpenProjectPluginCfg(marker));
        controlSearch(autoComplete, marker);
        supportHintItems(autoComplete);
        return editor;
      });
    }

    // Control when the work packages are searched, through the text watcher of the autocomplete, which matches the text
    // typed after the marker, and its model, which searches the matched text:
    // * AdvancedAutoComplete ignores the minChars option: it matches the marker followed by 0 to 30 characters, so the
    //   work packages would be searched as soon as the marker is typed. The text typed after the marker isn't matched
    //   until it has MIN_CHARS characters, so that the autocomplete panel isn't opened, or is closed, and nothing is
    //   searched. The matching of AdvancedAutoComplete is kept otherwise, since it depends on the XWiki version (e.g.
    //   whether the marker has to follow a space).
    // * Once a search returned no work package, the text that extends its query isn't matched anymore, since the search
    //   narrows as the query gets longer, so it can't match either (e.g. when the marker is followed by a sentence).
    //   Except for a query that can still become a work package key (e.g. XWI, then XWIKI-123), which is searched in
    //   the keys too, see isStoppedBy.
    // * Escape stops the search, as long as the text is typed after the same marker.
    // * The text is matched from the last occurrence of the marker, since AdvancedAutoComplete matches it from the first
    //   one of the 30 characters before the caret: the marker typed again on the same line starts a new search.
    // The search is stopped for one occurrence of the marker, identified by its position. It's forgotten when the text
    // before the caret no longer ends with this marker followed by text (e.g. the marker is deleted, the marker is
    // typed again, or the caret is moved elsewhere), so that typing the marker again searches again.
    function controlSearch(autoComplete, marker) {
      // The search stopped after a marker: its position, the beginning of the text typed after it whose search is
      // stopped (empty when the search is stopped whatever the text), and the entries to display instead of searching
      // (none when the autocomplete panel is closed).
      let stoppedSearch = null;
      const isAt = function (search, range) {
        return search?.node === range.startContainer.$ && search.offset === range.startOffset;
      };
      const isStoppedBy = function (search, text) {
        // A text shaped like a work package key is searched in the keys, which a text without dash isn't, so the
        // search of the beginning of a key (e.g. XWI for XWIKI-123) can return nothing while the key matches. A failed
        // search fails for any text, though.
        return search != null && text.startsWith(search.text)
          && !(!search.items.length && text !== search.text && IDENTIFIER.test(search.text)
            && KEY_BEGINNING.test(text));
      };
      const stopSearch = function (range, text, items) {
        // A stopped search isn't replaced by one that it already stops (e.g. the late response of a search done before
        // Escape was pressed).
        if (!isAt(stoppedSearch, range) || !isStoppedBy(stoppedSearch, text)) {
          stoppedSearch = {node: range.startContainer.$, offset: range.startOffset, text, items};
        }
      };

      const textWatcher = autoComplete.textWatcher;
      const matchFirstMarker = textWatcher.callback;
      const matchText = function (range) {
        const match = matchFirstMarker.apply(this, arguments);
        if (!match || match.text.indexOf(marker, marker.length) < 0) {
          return match;
        }
        // Match the text typed after the last occurrence of the marker instead.
        return ckeditor.plugins.textMatch.match(range, function (text, offset) {
          const start = text.slice(0, offset).lastIndexOf(marker);
          return start < 0 ? null : {start, end: offset};
        });
      };
      textWatcher.callback = function () {
        const match = matchText.apply(this, arguments);
        if (!match || !isAt(stoppedSearch, match.range)) {
          // The marker of the stopped search was deleted, or the text is typed after another marker.
          stoppedSearch = null;
        }
        const text = match ? getSearchText(match.text, marker) : '';
        if (text.trim().length < MIN_CHARS || (isStoppedBy(stoppedSearch, text) && !stoppedSearch.items.length)) {
          return null;
        }
        return match;
      };

      const model = autoComplete.model;
      const dataCallback = model.dataCallback;
      model.dataCallback = function (options, callback) {
        const text = getSearchText(options.query, marker);
        if (isStoppedBy(stoppedSearch, text)) {
          // Display the entries of the stopped search again, without searching.
          return callback(stoppedSearch.items);
        }
        // The marker position is taken before the search, since the user can keep typing while it's running.
        const range = options.range;
        const position = range && {startContainer: range.startContainer, startOffset: range.startOffset};
        return dataCallback.call(this, options, function (items) {
          if (position && Array.isArray(items) && !items.length) {
            stopSearch(position, text, []);
          } else if (position && Array.isArray(items) && items.some(item => item.failure)) {
            // The search would fail again, so its entry is displayed again for the text that extends the query.
            stopSearch(position, text, items);
          }
          return callback.apply(this, arguments);
        });
      };

      // The autocomplete only handles Escape when its panel is opened, and matches the text again at the next key, so
      // the work packages would be searched again.
      const onKeyDown = autoComplete.onKeyDown;
      autoComplete.onKeyDown = function (event) {
        if (event.data.getKey() === 27) {
          const range = this.editor.getSelection()?.getRanges()[0];
          const match = range && matchText.call(textWatcher, range);
          if (match) {
            stopSearch(match.range, '', []);
          }
        }
        return onKeyDown.apply(this, arguments);
      };
    }

    // The entries displayed instead of the work packages are displayed differently, and selecting them (with the
    // keyboard or the mouse) only closes the autocomplete panel, keeping the typed text.
    function supportHintItems(autoComplete) {
      const commit = autoComplete.commit;
      autoComplete.commit = function (itemId) {
        const selectedItemId = itemId ?? this.model.selectedItemId;
        if (selectedItemId != null && this.model.getItemById(selectedItemId)?.hint) {
          this.close();
        } else {
          return commit.apply(this, arguments);
        }
      };
      const view = autoComplete.view;
      const createItem = view.createItem;
      view.createItem = function (item) {
        if (!item.hint) {
          return createItem.apply(this, arguments);
        }
        const itemTemplate = this.itemTemplate;
        let element;
        try {
          this.itemTemplate = hintItemTemplate;
          element = createItem.apply(this, arguments);
        } finally {
          this.itemTemplate = itemTemplate;
        }
        // The message rendered by the server, whose links can be clicked.
        if (typeof item.html === 'string') {
          element.findOne('.ckeditor-autocomplete-item-label').setHtml(item.html);
        }
        return element;
      };
    }

    function waitForEditorReady(editor) {
      return new Promise((resolve, reject) => {
        if (editor.status === 'ready') {
          resolve(editor);
        } else {
          editor.once('instanceReady', (event) => {
            resolve(event.editor);
          });
        }
      });
    }
  });
});
